using System;using System.Linq;using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud08Menu{public static string Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var m=h.Sandbox.PauseMenu;return new JObject{{"open",m.IsOpen},{"blocks",m.BlocksInput},{"paused",h.Sandbox.Clock.Paused},{"alpha",m.Overlay.alpha},{"active",m.Overlay.gameObject.activeInHierarchy},{"confirm",m.NewGameConfirmation.activeSelf},{"developer",m.Developer.activeSelf},{"clock",h.Sandbox.Clock.RemainingSeconds},{"enabled",m.enabled},{"frame",Time.frameCount},{"components",new JArray(h.GetComponents<HudPauseMenu>().Select(x=>x.name))}}.ToString();}}
